#include "lgw_bt_planner/named_target_loader.hpp"
#include "lgw_bt_planner/xacro_condition_filter.hpp"

#include <ament_index_cpp/get_package_share_directory.hpp>
#include <fstream>
#include <regex>
#include <sstream>

namespace lgw_bt_planner
{

namespace
{
// Note: read the .xacro source, not the .srdf. The .srdf in the install dir is
// a stale autogenerated artifact (last touched at install time) that contains
// only `<group_state name="home">`; the gripper / hand group_states live inside
// `<xacro:if value="$(eval effector_type == 'agx_gripper')">` wrappers in the
// xacro. move_group's _moveit_config_builder loads the xacro at runtime with
// effector_type:=agx_gripper, so it sees the gripper states; the loader here
// must read the same xacro to match.
//
// 2026-11-17: the plain-text regex parse used to keep the text of *every*
// branch, so states sharing a name clobbered each other — the nero `home`
// (7 joints, including joint7) overwrote the piper `home` (6 joints) and the BT
// ended up commanding a joint the arm does not have. strip_inactive_xacro_blocks()
// now removes inactive branches first, using the same arm_type / effector_type /
// revo2_type arguments the xacro itself takes.
constexpr const char* kSrdfSubpath = "/config/agx_arm.srdf.xacro";

// Matches <group_state ... name="X" ... group="Y" ...> ... </group_state>
// in any attribute order. Captures name and group; ignores intermediate attrs.
const std::regex kGroupStateRegex(
  R"(<group_state\b((?:\s+[a-zA-Z_][\w:]*=\"[^\"]*\")+?)\s*>([\s\S]*?)</group_state>)");
const std::regex kAttrRegex(R"(\s+(name|group)=\"([^\"]+)\")");

// Matches <joint name="J" value="V" /> inside a group_state.
const std::regex kJointValueRegex(
  R"(<joint\s+name=\"([^\"]+)\"\s+value=\"([-+]?\d+(?:\.\d+)?)\"\s*/?>)");
}  // namespace

TargetTable NamedTargetLoader::load_from_share(
  const std::string& arm_type,
  const std::string& effector_type,
  const std::string& revo2_type)
{
  const std::string pkg_share =
    ament_index_cpp::get_package_share_directory("agx_arm_moveit");
  const std::string srdf_path = pkg_share + kSrdfSubpath;

  std::ifstream ifs(srdf_path);
  if (!ifs.is_open()) {
    throw std::runtime_error("NamedTargetLoader: cannot open SRDF: " + srdf_path);
  }

  std::stringstream ss;
  ss << ifs.rdbuf();
  const std::string raw = ss.str();
  const std::string content = strip_inactive_xacro_blocks(
    raw, arm_type, effector_type, revo2_type);

  TargetTable table;

  auto state_begin = std::sregex_iterator(content.begin(), content.end(), kGroupStateRegex);
  auto state_end = std::sregex_iterator();

  for (auto it = state_begin; it != state_end; ++it) {
    const std::string attrs = (*it)[1].str();
    const std::string state_body = (*it)[2].str();
    std::string state_name;
    std::string state_group;

    auto a_begin = std::sregex_iterator(attrs.begin(), attrs.end(), kAttrRegex);
    auto a_end = std::sregex_iterator();
    for (auto at = a_begin; at != a_end; ++at) {
      const std::string key = (*at)[1].str();
      const std::string val = (*at)[2].str();
      if (key == "name") state_name = val;
      else if (key == "group") state_group = val;
    }
    if (state_name.empty() || state_group.empty()) continue;

    std::map<std::string, double> joints;
    auto j_begin = std::sregex_iterator(state_body.begin(), state_body.end(), kJointValueRegex);
    auto j_end = std::sregex_iterator();

    for (auto jt = j_begin; jt != j_end; ++jt) {
      const std::string j_name = (*jt)[1].str();
      const double j_value = std::stod((*jt)[2].str());
      joints[j_name] = j_value;
    }

    if (!joints.empty()) {
      NamedTarget nt;
      nt.group = state_group;
      nt.joints = std::move(joints);
      table[state_name] = std::move(nt);
    }
  }

  return table;
}

std::vector<double> NamedTargetLoader::get_joint_values(
  const TargetTable& table,
  const std::string& target,
  const std::vector<std::string>& joint_names)
{
  auto it = table.find(target);
  if (it == table.end()) {
    throw std::runtime_error("NamedTargetLoader: unknown target '" + target + "'");
  }
  const auto& joints = it->second.joints;

  std::vector<double> values;
  values.reserve(joint_names.size());
  for (const auto& jn : joint_names) {
    auto jt = joints.find(jn);
    values.push_back(jt == joints.end() ? 0.0 : jt->second);
  }
  return values;
}

}  // namespace lgw_bt_planner